export const getSubmitSubmissionUrl = (submissionId: SubmissionId) => {
  return `/api/v2/submissions/${submissionId}/submit`
}

/**
 * Optionally applies a last answer patch. `If-Match` is honoured when
 * present. With an `Idempotency-Key`, a retry with the same body replays
 * the original response for 24h; the same key with a different body is
 * 422. Limited to 3 submits per 10 seconds per learner.
 * @summary Submit the draft for grading.
 */
export const submitSubmission = async (
  submissionId: SubmissionId,
  submitRequest: SubmitRequest,
  options?: Parameters<typeof orvalMutator>[1],
): Promise<StudentSubmission> => {
  const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {}
    if (h instanceof Headers) return Object.fromEntries(h.entries())
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, entry => Array.from(entry) as [string, string]),
      )
    }
    const headers: Record<string, string | readonly string[]> = {}
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value
    }
    return headers
  }
  return orvalMutator<StudentSubmission>(
    getSubmitSubmissionUrl(submissionId),
    {
      ...options,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
      body: JSON.stringify(submitRequest),
    },
    StudentSubmission,
  )
}

